method rolling_max(numbers: seq<int>): seq<int>
    requires |numbers| > 0
    ensures |result| == |numbers|
    ensures forall i :: 0 <= i < |result| ==> result[i] == Max(numbers[0..i+1])
    returns result
{
    var result := new int[|numbers|];
    var currentMax := numbers[0];

    result[0] := currentMax;
    var i := 1;

    while i < |numbers|
        invariant 0 <= i <= |numbers|
        invariant forall j :: 0 <= j < i ==> result[j] == Max(numbers[0..j+1])
        invariant currentMax == Max(numbers[0..i])
    {
        if numbers[i] > currentMax {
            currentMax := numbers[i];
        }
        result[i] := currentMax;
        i := i + 1;
    }

    return result;
}
